-- #578 Profil v12 (UX önerileri kanvası `Profil_v12_Arkadas` · `Profil_v12_Kendi`): il il Türkiye haritası, gitmek istenen
-- yerler, rozetler ve geziler. Veri silme yok; Google'a istek yok.
--
-- KK3 · gittiği iller kendi verimizden: bitmiş seyahatin şehri ve gezilen durakların ili. İl, saklı koordinattan il sınırı
--   içinde-mi testiyle bulunur (`il_bul`); koordinatı olmayan durak sayılmaz. Şehrin koordinatı boşaldıysa (gece temizliği,
--   20261210000000) yalnız il adıyla birebir eşleşen şehir etiketi sayılır. Hiçbir şey saklanmaz: il her okumada canlı
--   koordinattan hesaplanır; Google'dan gelen yeni bir alan yazılmaz (PRD §7). Sonuç: gece temizliği 30 günü geçen
--   koordinatı boşalttığında o durağın ili haritadan düşer (il plakasını saklamak Ürün kararı bekliyor, PR #600).
--   Sınırlar: `src/assets/turkiye-iller.json` (turkey-map-react 2.4.6, MIT, © 2020 Erdi Gökçe) yollarından
--   `scripts/il-sinirlari.mjs` ile üretildi; haritanın SVG biriminde (viewBox 0 0 1050 585 civarı). Yollar Lambert konik
--   konform izdüşümünde çizilmiş: n = 0.5531, merkez boylam 32.8563°, ardından ölçek, dönme ve öteleme (`il_noktasi`).
--   Parametreler 81 il merkezine uydurularak bulundu; harita kıyıda ±2 km kaba olduğundan sınırın 8 birim (~14 km)
--   yakınındaki nokta en yakın ile sayılır (kıyı, ada). Yalnız Türkiye seyahatleri (country_code TR ya da boş) sayılır.
-- KK4 · `istek_iller(user_id, plaka)`: sahibi yazar ve siler; birlikte gezdiği kişiler (arkadaşları) okur.
-- KK5 · rozetler sunucuda bir görünümle (`profil_rozetleri`): gezilen durak = bitmiş seyahatte güne atanmış, atlanmamış
--   durak (`seyahat_durumlari` ile aynı kural). Lezzet (yemek, tatlı-kahve), Doğa (doğa), Kültür (müze, tarih): il
--   listesinde (`il_oneriler`) o kategoride olan gezilen yer sayısı. Ekip: aynı kişilerle (aynı yol arkadaşı kümesiyle)
--   yapılan bitmiş gezi sayısının en büyüğü. Plancı: kurduğu ve en az bir kişinin katıldığı gezi sayısı. Eşik 3.
-- KK6 · arkadaşın profilinde yalnız geçmiş geziler; harita ve geziler `profiles.map_visibility` ile ('me' ise arkadaş
--   görmez). Okuma yalnız `profil_ozeti` (security definer) ile; görünümler ve sınır tablosu istemciye kapalı.

-- ---------------------------------------------------------------- iller ve sınırları

create table public.iller (
  plaka smallint primary key check (plaka between 1 and 81),
  ad text not null unique check (char_length(ad) between 1 and 40),
  slug text not null unique check (slug ~ '^[a-z]{3,20}$')
);
alter table public.iller enable row level security;
create policy iller_oku on public.iller for select to anon, authenticated using (true);
revoke all on public.iller from public, anon, authenticated;
grant select on public.iller to anon, authenticated;

