-- Bir ilin her parçası (ada, Boğaz'ın iki yakası, göl) ayrı halka; içerde-mi çift-tek kuralıyla (halkanın içindeki göl
-- ile değil).
create table public.il_sinirlari (
  plaka smallint not null references public.iller (plaka),
  parca smallint not null check (parca >= 1),
  sinir polygon not null,
  kutu box not null,
  primary key (plaka, parca)
);
alter table public.il_sinirlari enable row level security;
revoke all on public.il_sinirlari from public, anon, authenticated;
-- Politika yok: yalnız security definer fonksiyonlar okur.

