-- Enlem/boylamın haritadaki (SVG) noktası. Lambert konik konform (küre), sonra benzerlik dönüşümü; y aşağı doğru.
create function public.il_noktasi(p_lat double precision, p_lng double precision) returns point
language sql immutable parallel safe set search_path = ''
as $$
  with k as (
    select 0.5530963 as n, 32.8562656 as lng0, 4533.3776 as s, -0.0374546 as r, 589.92552 as tx, -5067.7272 as ty
  ), p as (
    select k.*,
      power(tan(pi() / 4 + radians(p_lat) / 2), -k.n) / k.n as rho,
      k.n * radians(p_lng - k.lng0) as th
    from k
  ), q as (
    select p.*, p.rho * sin(p.th) as x0, -p.rho * cos(p.th) as y0 from p
  )
  select point(
    q.s * (q.x0 * cos(q.r) - q.y0 * sin(q.r)) + q.tx,
    -q.s * (q.x0 * sin(q.r) + q.y0 * cos(q.r)) + q.ty)
  from q
$$;

-- Koordinatın ili (plaka) ya da null. Önce içinde olduğu il; yoksa 8 birim (~14 km) içindeki en yakın il.
create function public.il_bul(p_lat double precision, p_lng double precision) returns smallint
language sql stable security definer set search_path = ''
as $$
  with n as (
    select public.il_noktasi(p_lat, p_lng) as n
    where p_lat between -90 and 90 and p_lng between -180 and 180
  )
  select coalesce(
    (select s.plaka from public.il_sinirlari s, n
      where s.kutu @> n.n and s.sinir @> n.n
      group by s.plaka having count(*) % 2 = 1
      order by s.plaka limit 1),
    (select y.plaka from (
       select s.plaka, n.n <-> s.sinir as uzaklik from public.il_sinirlari s, n order by 2 limit 1) y
      where y.uzaklik <= 8))
$$;

-- Şehir etiketinden il (yalnız il adıyla birebir; "Bodrum" gibi ilçe adı eşleşmez). Virgülden sonrası atılır.
create function public.il_adi_sade(p text) returns text
language sql immutable parallel safe set search_path = ''
as $$
  select lower(translate(btrim(split_part(p, ',', 1)), 'ÇĞİIÖŞÜÂÎÛçğıöşüâîû', 'CGIIOSUAIUcgiosuaiu'))
$$;

revoke all on function public.il_noktasi(double precision, double precision), public.il_bul(double precision, double precision),
  public.il_adi_sade(text) from public, anon, authenticated;
-- Yalnız bu dosyadaki görünüm ve fonksiyonlar çağırır; istemciye açık değil.

-- ---------------------------------------------------------------- KK4 · gitmek istenen iller

create table public.istek_iller (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  plaka smallint not null references public.iller (plaka),
  created_at timestamptz not null default now(),
  primary key (user_id, plaka)
);
alter table public.istek_iller enable row level security;
revoke all on public.istek_iller from public, anon, authenticated;
grant select, delete on public.istek_iller to authenticated;
grant insert (plaka) on public.istek_iller to authenticated;
-- Sahibi ve birlikte gezdiği kişiler (arkadaşları; `ortak_seyahat_var`, 20261119010000) okur; misafir oturum okumaz.
create policy istek_iller_select on public.istek_iller for select to authenticated
  using (not public.is_anonymous() and (user_id = auth.uid() or public.ortak_seyahat_var(user_id)));
-- Yalnız sahibi, hesaplı oturumla yazar (misafir oturum yazmaz).
create policy istek_iller_insert on public.istek_iller for insert to authenticated
  with check (user_id = auth.uid() and not public.is_anonymous());
create policy istek_iller_delete on public.istek_iller for delete to authenticated using (user_id = auth.uid());

-- ---------------------------------------------------------------- KK3 · gittiği iller

create view public.gidilen_iller as
  select distinct x.user_id, x.plaka
  from (
    -- Bitmiş seyahatin şehri: koordinattan; koordinat boşaldıysa il adıyla.
    select m.user_id,
      coalesce(public.il_bul(t.lat, t.lng), (select i.plaka from public.iller i where i.slug = public.il_adi_sade(t.city_label))) as plaka
    from public.members m
    join public.trips t on t.id = m.trip_id
    where public.seyahat_bitti(t.end_date, t.tz) and (t.country_code is null or t.country_code = 'TR')
    union all
    -- Gezilen durak: koordinatı olan, atlanmamış durak.
    select m.user_id, public.il_bul(p.lat, p.lng)
    from public.members m
    join public.trips t on t.id = m.trip_id
    join public.stops s on s.trip_id = t.id and not s.skipped
    join public.places p on p.id = s.place_ref
    where public.seyahat_bitti(t.end_date, t.tz) and (t.country_code is null or t.country_code = 'TR') and p.lat is not null
  ) x
  where x.plaka is not null;
revoke all on public.gidilen_iller from public, anon, authenticated;

-- ---------------------------------------------------------------- KK5 · rozetler

create view public.profil_rozetleri as
  with gezilen as (
    select distinct m.user_id, p.place_id
    from public.members m
    join public.trips t on t.id = m.trip_id
    join public.stops s on s.trip_id = t.id and not s.skipped
    join public.places p on p.id = s.place_ref
    where public.seyahat_bitti(t.end_date, t.tz)
  )
  select pr.id as user_id,
    (select count(*) from gezilen g where g.user_id = pr.id and exists (
       select 1 from public.il_oneriler o where o.place_id = g.place_id and o.gorunur and o.kategori in ('yemek', 'tatli_kahve')))::integer as lezzet,
    (select count(*) from gezilen g where g.user_id = pr.id and exists (
       select 1 from public.il_oneriler o where o.place_id = g.place_id and o.gorunur and o.kategori = 'doga'))::integer as doga,
    (select count(*) from gezilen g where g.user_id = pr.id and exists (
       select 1 from public.il_oneriler o where o.place_id = g.place_id and o.gorunur and o.kategori in ('muze', 'tarih')))::integer as kultur,
    -- Aynı yol arkadaşı kümesiyle yapılan bitmiş gezi sayısının en büyüğü (tek başına gezi sayılmaz).
    (select coalesce(max(e.n), 0) from (
       select count(*) as n from (
         select t.id, array_agg(o.user_id order by o.user_id) as kume
         from public.members m
         join public.trips t on t.id = m.trip_id
         join public.members o on o.trip_id = t.id and o.user_id <> m.user_id
         where m.user_id = pr.id and public.seyahat_bitti(t.end_date, t.tz)
         group by t.id) k
       group by k.kume) e)::integer as ekip,
    (select count(*) from public.trips t where t.owner_id = pr.id
       and exists (select 1 from public.members o where o.trip_id = t.id and o.user_id <> pr.id))::integer as planci
  from public.profiles pr;
revoke all on public.profil_rozetleri from public, anon, authenticated;

-- ---------------------------------------------------------------- profil özeti

-- Kendi profilin ya da birlikte gezdiğin kişinin profili; başkası için null.
-- Arkadaşta: harita ve geziler `map_visibility = 'me'` ise yok; geziler yalnız bitmiş olanlar (KK6); kazanılmamış rozetin
-- sayısı dönmez (KK5). Gezideki diğer kişilerden yalnız baş harf; fotoğraf yalnız izleyenin de birlikte gezdiği kişininki.
create function public.profil_ozeti(p_kisi uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  ben uuid := auth.uid();
  kendi boolean := p_kisi = auth.uid();
  pr public.profiles;
  acik boolean;
  r public.profil_rozetleri;
begin
  if ben is null or p_kisi is null or public.is_anonymous() then
    return null;
  end if;
  if not kendi and not public.ortak_seyahat_var(p_kisi) then
    return null;
  end if;
  select * into pr from public.profiles where id = p_kisi;
  if pr.id is null then
    return null;
  end if;
  acik := kendi or pr.map_visibility <> 'me';
  select * into r from public.profil_rozetleri where user_id = p_kisi;
  return jsonb_build_object(
    'id', pr.id,
    'ad', pr.name,
    'foto', pr.photo_url,
    'kendi', kendi,
    'gizlilik', case when kendi then pr.map_visibility end,
    'harita_acik', acik,
    'gidilen', case when acik then coalesce((
      select jsonb_agg(g.plaka order by g.plaka) from public.gidilen_iller g where g.user_id = p_kisi), '[]'::jsonb) end,
    'istek', coalesce((select jsonb_agg(i.plaka order by i.created_at, i.plaka) from public.istek_iller i where i.user_id = p_kisi), '[]'::jsonb),
    'benim_istek', case when kendi then null else coalesce((
      select jsonb_agg(i.plaka order by i.plaka) from public.istek_iller i where i.user_id = ben), '[]'::jsonb) end,
    'yol_arkadasi', (
      select count(distinct o.user_id) from public.members m join public.members o on o.trip_id = m.trip_id and o.user_id <> m.user_id
      where m.user_id = p_kisi),
    'rozetler', jsonb_strip_nulls(jsonb_build_object(
      'lezzet', case when kendi or r.lezzet >= 3 then r.lezzet end,
      'doga', case when kendi or r.doga >= 3 then r.doga end,
      'kultur', case when kendi or r.kultur >= 3 then r.kultur end,
      'ekip', case when kendi or r.ekip >= 3 then r.ekip end,
      'planci', case when kendi or r.planci >= 3 then r.planci end)),
    'geziler', case when not acik then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', t.id,
          'sehir', t.city_label,
          'ad', t.name,
          'start_date', t.start_date,
          'end_date', t.end_date,
          'tz', t.tz,
          'gun_sayisi', (select count(*) from public.days d where d.trip_id = t.id),
          'durak_sayisi', (select count(*) from public.stops s where s.trip_id = t.id),
          'kisi_sayisi', (select count(*) from public.members o where o.trip_id = t.id),
          'bitti', public.seyahat_bitti(t.end_date, t.tz),
          'uyesiyim', public.is_member(t.id),
          'kisiler', coalesce((
            select jsonb_agg(jsonb_build_object(
                'harf', left(btrim(o.display_name), 1),
                -- Yüz rengi kişiye bağlı ve sabit; kimlik dönmez.
                'renk', (abs(hashtext(o.user_id::text)::bigint) % 3)::integer,
                'foto', case when o.user_id = ben or public.ortak_seyahat_var(o.user_id) then (
                  select f.photo_url from public.profiles f where f.id = o.user_id) end)
              order by o.joined_at, o.user_id)
            from public.members o where o.trip_id = t.id and o.user_id <> p_kisi), '[]'::jsonb))
        order by public.seyahat_bitti(t.end_date, t.tz), case when public.seyahat_bitti(t.end_date, t.tz) then null else t.start_date end,
          t.end_date desc, t.id)
      from public.members m
      join public.trips t on t.id = m.trip_id
      where m.user_id = p_kisi and t.start_date is not null
        and (kendi or public.seyahat_bitti(t.end_date, t.tz))), '[]'::jsonb) end
  );
end;
$$;
revoke all on function public.profil_ozeti(uuid) from public, anon, authenticated;
grant execute on function public.profil_ozeti(uuid) to authenticated;
